// This file is generated by AI.

// 查看历史对话框: 分支信息 + 提交列表 (可展开查看详情与文件变更, 支持还原)。
//
// 状态跨打开保留: 打开场景差异 / Esc 自动关闭时不重置; 仅"关闭"按钮手动关闭才重置。

import { Button } from '@fluentui/react-components';
import { ArrowClockwiseRegular, BranchForkRegular, HistoryRegular } from '@fluentui/react-icons';
import { useEffect, useRef, useState } from 'react';

import { gitCommitFiles, gitLog, gitRestore, gitRestoreAll, type GitCommit, type GitCommitFile } from '../commands/git';
import { openGitDiff } from '../git/diff';
import { refreshGitStatus } from '../git/status';
import { STATUS_CLASS } from '../git/util';
import { useAppStore } from '../state/store';
import { middleEllipsis } from './FileTree';

/** 跨打开保留的历史状态 (打开场景差异 / Esc 关闭时不清空, 仅"关闭"按钮重置) */
interface HistoryPersist {
  commits: GitCommit[];
  expanded: string | null;
  files: Record<string, GitCommitFile[]>;
  scrollTop: number;
}
let persisted: HistoryPersist | null = null;

interface Props {
  onClose: () => void;
}

function formatDate(seconds: number): string {
  const d = new Date(seconds * 1000);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export function GitHistoryDialog({ onClose }: Props) {
  const projectPath = useAppStore((s) => s.projectPath);
  const branch = useAppStore((s) => s.gitStatus?.branch ?? null);

  const [commits, setCommits] = useState<GitCommit[]>(persisted?.commits ?? []);
  const [expanded, setExpanded] = useState<string | null>(persisted?.expanded ?? null);
  const [files, setFiles] = useState<Record<string, GitCommitFile[]>>(persisted?.files ?? {});
  const listRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [menu, setMenu] = useState<{ file: GitCommitFile; commitId: string; x: number; y: number } | null>(null);

  // 恢复 / 初次加载
  useEffect(() => {
    if (!projectPath) return;
    if (!persisted) {
      gitLog(projectPath)
        .then((list) => {
          setCommits(list);
          persisted = { commits: list, expanded: null, files: {}, scrollTop: 0 };
        })
        .catch((e) => setError(String(e)));
      return;
    }
    // 恢复滚动位置
    requestAnimationFrame(() => {
      if (listRef.current) listRef.current.scrollTop = persisted?.scrollTop ?? 0;
    });
  }, [projectPath]);

  // 记录滚动位置
  useEffect(() => {
    const el = listRef.current;
    if (!el || !persisted) return;
    const onScroll = () => {
      if (persisted) persisted.scrollTop = el.scrollTop;
    };
    el.addEventListener('scroll', onScroll);
    return () => el.removeEventListener('scroll', onScroll);
  }, []);

  // 手动"关闭"按钮: 重置状态
  const manualClose = () => {
    persisted = null;
    onClose();
  };

  // Esc 视为自动关闭 (保留状态)
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  useEffect(() => {
    if (!menu) return;
    const close = () => setMenu(null);
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('scroll', close, { capture: true });
    window.addEventListener('resize', close);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('scroll', close, { capture: true });
      window.removeEventListener('resize', close);
    };
  }, [menu]);

  if (!projectPath) return null;

  const toggle = async (id: string) => {
    const next = expanded === id ? null : id;
    setExpanded(next);
    if (persisted) persisted.expanded = next;
    if (next && !files[id]) {
      try {
        const list = await gitCommitFiles(projectPath, id);
        setFiles((prev) => {
          const merged = { ...prev, [id]: list };
          if (persisted) persisted.files = merged;
          return merged;
        });
      } catch (e) {
        setError(String(e));
      }
    }
  };

  const run = async (fn: () => Promise<unknown>) => {
    if (busy) return;
    setBusy(true);
    try {
      await fn();
      await refreshGitStatus(projectPath);
      setExpanded(null);
      if (persisted) persisted.expanded = null;
    } catch (e) {
      setError(String(e));
    } finally {
      setBusy(false);
    }
  };

  const fileRow = (file: GitCommitFile, commitId: string) => {
    const cls = STATUS_CLASS[file.status] ?? '';
    return (
      <button
        key={file.path}
        className="git-file-item"
        onClick={() => {
          openGitDiff(file.path, 'commit', commitId);
          onClose(); // 打开差异后自动关闭历史 (保留状态)
        }}
        onContextMenu={(e) => {
          e.preventDefault();
          setMenu({
            file,
            commitId,
            x: Math.min(e.clientX, window.innerWidth - 200),
            y: Math.min(e.clientY, window.innerHeight - 120),
          });
        }}
        title={file.path}
      >
        <span className={`git-file-status ${cls}`}>{file.status}</span>
        <span className="git-file-name">{middleEllipsis(file.path, 40)}</span>
        <span className="git-file-stats">
          {file.additions > 0 ? <em className="git-add">+{file.additions}</em> : null}
          {file.deletions > 0 ? <em className="git-del">-{file.deletions}</em> : null}
        </span>
      </button>
    );
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-surface history-surface" onClick={(e) => e.stopPropagation()}>
        <div className="history-header">
          <h2 className="modal-title">提交历史</h2>
          <span className="repository-branch">
            <BranchForkRegular /> {branch ?? '当前分支'}
          </span>
          <span className="history-header-spacer" />
          <Button appearance="secondary" onClick={manualClose}>
            关闭
          </Button>
        </div>

        <div className="history-list" ref={listRef}>
          {commits.length === 0 ? (
            <div className="muted repository-empty-list">暂无提交记录</div>
          ) : (
            commits.map((c) => (
              <div key={c.id} className="git-commit">
                <div className="git-commit-row" onClick={() => void toggle(c.id)}>
                  <span className="git-commit-toggle">{expanded === c.id ? '▾' : '▸'}</span>
                  <span className="git-commit-summary" title={c.summary}>
                    {middleEllipsis(c.summary, 60)}
                  </span>
                  <span className="git-commit-time">{formatDate(c.time)}</span>
                  <span className="git-file-stats">
                    {c.additions > 0 ? <em className="git-add">+{c.additions}</em> : null}
                    {c.deletions > 0 ? <em className="git-del">-{c.deletions}</em> : null}
                  </span>
                </div>
                {expanded === c.id ? (
                  <div className="git-commit-detail">
                    <div className="git-commit-detail-info">
                      <pre className="git-commit-message">{c.message}</pre>
                      <div className="git-commit-meta">
                        <span>ID: {c.id}</span>
                        <span>作者: {c.author}</span>
                      </div>
                    </div>
                    <div className="git-commit-detail-files">{(files[c.id] ?? []).map((f) => fileRow(f, c.id))}</div>
                  </div>
                ) : null}
              </div>
            ))
          )}
        </div>

        {menu ? (
          <>
            <div
              className="context-menu-backdrop"
              onClick={() => setMenu(null)}
              onContextMenu={(e) => {
                e.preventDefault();
                setMenu(null);
              }}
            />
            <div className="context-menu" style={{ left: menu.x, top: menu.y }}>
              <button
                className="context-menu-item"
                onClick={() => {
                  setMenu(null);
                  void run(() => gitRestore(projectPath, [menu.file.path], menu.commitId));
                }}
              >
                <ArrowClockwiseRegular />
                还原
              </button>
              <button
                className="context-menu-item"
                onClick={() => {
                  setMenu(null);
                  void run(() => gitRestoreAll(projectPath, menu.commitId));
                }}
              >
                <HistoryRegular />
                还原全部
              </button>
            </div>
          </>
        ) : null}

        {error ? (
          <div className="history-error">
            <span className="prompt-error">{error}</span>
            <Button appearance="secondary" size="small" onClick={() => setError(null)}>
              关闭
            </Button>
          </div>
        ) : null}
      </div>
    </div>
  );
}
